package practice;

import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;

/**
 * Starts the integration connectors (warehouse, billing, shipping, ...) when the order service
 * boots. Each connector's constructor opens its connection, and may fail when the other side is
 * down.
 */
public class ConnectorFactory {

    /** What every connector class implements. */
    public interface Connector {
        String name();
    }

    /** A connector that could not be started. */
    public static class ConnectorException extends Exception {
        public ConnectorException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    private final List<String> skipped = new ArrayList<>();

    /** Starts every connector it can, skipping the ones that can't be started. */
    public List<Connector> createAll(List<Class<? extends Connector>> types) {
        List<Connector> started = new ArrayList<>();
        for (Class<? extends Connector> type : types) {
            try {
                started.add(create(type));
            } catch (ConnectorException e) {
                skipped.add(type.getSimpleName() + ": " + e.getCause());
            }
        }
        return started;
    }

    /** One line per connector that createAll skipped, with the reason. */
    public List<String> skipped() {
        return List.copyOf(skipped);
    }

    public Connector create(Class<? extends Connector> type) throws ConnectorException {
        try {
            return type.getDeclaredConstructor().newInstance();
        } catch (InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof RuntimeException unchecked) throw unchecked;
            if (cause instanceof Error error) throw error;
            throw new ConnectorException(type.getSimpleName() + " could not start", cause);
        } catch (ReflectiveOperationException e) {
            throw new ConnectorException("cannot create " + type.getName(), e);
        }
    }
}

package practice;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ConnectorFactory factory = new ConnectorFactory();
            List<ConnectorFactory.Connector> started = factory.createAll(List.of(Payments.class, Freight.class, Crm.class));
            System.out.println("started: " + started.stream().map(ConnectorFactory.Connector::name).toList());
            System.out.println("skipped: " + factory.skipped());
            try {
                factory.create(Freight.class);
            } catch (ConnectorFactory.ConnectorException e) {
                System.out.println("cause: " + e.getCause());
            }
            try {
                factory.create(Promo.class);
            } catch (IllegalStateException bug) {
                System.out.println("bug reaches caller as: " + bug);
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    public static class Payments implements ConnectorFactory.Connector {
        public String name() { return "payments"; }
    }
    public static class Crm implements ConnectorFactory.Connector {
        public String name() { return "crm"; }
    }
    public static class Freight implements ConnectorFactory.Connector {
        public Freight() throws java.net.ConnectException {
            throw new java.net.ConnectException("freight.example.invalid:443 unreachable");
        }
        public String name() { return "freight"; }
    }
    public static class Promo implements ConnectorFactory.Connector {
        public Promo() { throw new IllegalStateException("promo codes table missing"); }
        public String name() { return "promo"; }
    }
}

